# *args (Multiple arguments)
def add_all(*args):
    return sum(args)

print("Sum:", add_all(1, 2, 3, 4))

# **kwargs (Keyword arguments)
def profile(**kwargs):
    for key, val in kwargs.items():
        print(f"{key}: {val}")

profile(name="Alice", role="Admin")

def check_age(age):
    if age < 0:
        raise ValueError("Age cannot be negative!")
    return age

try:
    check_age(-5)
except ValueError as e:
    print(f"Caught an error: {e}")
except TypeError:
    print("Invalid data type!")
finally:
    print("Verification attempt finished.")

import json

# Polymorphism Example
class Bird:
    def speak(self): return "Chirp"
class Duck(Bird):
    def speak(self): return "Quack" # Overriding

animals = [Bird(), Duck()]
for a in animals:
    print(a.speak())

# JSON Dumping (Dict to String)
user = {"name": "Alice", "active": True}
json_str = json.dumps(user, indent=2)
print("\nJSON Output:\n" + json_str)
